package com.alan.thormonitor;
import android.app.*;import android.graphics.*;import android.widget.*;import android.view.*;import java.io.*;import java.util.*;import com.google.zxing.*;import com.google.zxing.common.BitMatrix;
final class WebQr {
 static Bitmap bitmap(String address)throws Exception{if(!WebOps.urlList().contains(address))throw new IllegalArgumentException("Start Web Ops on a private network first");BitMatrix bits=new MultiFormatWriter().encode(address,BarcodeFormat.QR_CODE,600,600);Bitmap image=Bitmap.createBitmap(600,600,Bitmap.Config.ARGB_8888);int[] pixels=new int[600*600];for(int y=0;y<600;y++)for(int x=0;x<600;x++)pixels[y*600+x]=bits.get(x,y)?Color.BLACK:Color.WHITE;image.setPixels(pixels,0,600,0,0,600,600);return image;}
 static byte[] png(String address)throws Exception{Bitmap image=bitmap(address);try{ByteArrayOutputStream out=new ByteArrayOutputStream();image.compress(Bitmap.CompressFormat.PNG,100,out);return out.toByteArray();}finally{image.recycle();}}
 private static Dialog dialog(Activity a,HostStatsUi ui,LinearLayout content){Dialog dialog=new Dialog(a);content.setPadding(ui.dp(22),ui.dp(22),ui.dp(22),ui.dp(18));content.setBackground(ui.shape(ui.p.card,22));ScrollView scroll=new ScrollView(a);scroll.addView(content);dialog.setContentView(scroll);dialog.getWindow().setBackgroundDrawableResource(android.R.color.transparent);dialog.show();dialog.getWindow().setLayout(Math.min(ui.dp(420),a.getResources().getDisplayMetrics().widthPixels-ui.dp(32)),-2);if(a instanceof MainActivity)((MainActivity)a).controllerDialog(dialog);if(android.animation.ValueAnimator.areAnimatorsEnabled()){content.setAlpha(0);content.animate().alpha(1).setDuration(220).start();}return dialog;}
 static void show(Activity a){List<String> urls=WebOps.urlList();if(urls.isEmpty()){Toast.makeText(a,"Start Web Ops and connect to Wi-Fi or a private VPN",Toast.LENGTH_LONG).show();return;}HostStatsUi ui=new HostStatsUi(a);LinearLayout content=ui.vertical();content.addView(ui.text("Open Web Ops",24,true));ui.gap(content,12);content.addView(ui.muted("Choose an address to show its QR code.",16));final Dialog[] choice={null};for(String url:urls){ui.gap(content,8);content.addView(ui.button(url,()->{choice[0].dismiss();try{Bitmap bitmap=bitmap(url);LinearLayout panel=ui.vertical();panel.addView(ui.text("Scan to connect",24,true));ui.gap(panel,16);ImageView image=new ImageView(a);image.setImageBitmap(bitmap);image.setScaleType(ImageView.ScaleType.FIT_CENTER);image.setContentDescription("Web Ops address QR code");panel.addView(image,new LinearLayout.LayoutParams(-1,ui.dp(240)));ui.gap(panel,12);TextView label=ui.text(url,16,false);label.setTextIsSelectable(true);panel.addView(label);ui.gap(panel,8);panel.addView(ui.muted("Sign in with your owner login.",15));final Dialog[] qr={null};ui.gap(panel,14);panel.addView(ui.button("Done",()->qr[0].dismiss()));qr[0]=dialog(a,ui,panel);qr[0].setOnDismissListener(d->bitmap.recycle());}catch(Exception e){Toast.makeText(a,"QR code unavailable",Toast.LENGTH_LONG).show();}}));}choice[0]=dialog(a,ui,content);}
}
